'use strict';
(async()=>{const $=s=>document.querySelector(s),esc=Atlas.esc,allowed=['heroes','monsters','npcs','static-items'],cache={},params=new URLSearchParams(location.search);let media={},items=[],records=[],ticket=0,renderTicket=0;const canonical=v=>v===undefined?'__MISSING__':JSON.stringify(v,(_,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a.localeCompare(b))):x);
async function load(table){if(!allowed.includes(table))throw Error('Unsupported collection');if(!cache[table]){const r=await fetch('data/'+table+'.json');if(!r.ok)throw Error('Could not load '+table);cache[table]=await r.json()}return cache[table]}
async function search(){const t=++ticket;try{const table=$('#compare-table').value,rows=await load(table);if(t!==ticket)return;const q=$('#compare-query').value.trim().toLowerCase(),found=rows.filter(r=>(r.id+' '+(r.fields.Name||'')+' '+(media[table+':'+r.id]?.name||'')).toLowerCase().includes(q));$('#compare-results').innerHTML=found.slice(0,25).map(r=>`<button data-add="${r.id}">${esc(media[table+':'+r.id]?.name||r.fields.Name||r.id)} · #${r.id}</button>`).join('');$('#compare-status').textContent=`${found.length} matches · first ${Math.min(25,found.length)} shown. Select a result to add it.`}catch(e){$('#compare-status').textContent=e.message}}
async function render(){const token=++renderTicket;const loaded=await Promise.all(items.map(async item=>({item,row:(await load(item.table)).find(r=>String(r.id)===String(item.id))})));if(token!==renderTicket)return;records=loaded;const invalid=records.filter(x=>!x.row);if(invalid.length)$('#compare-status').textContent='Some shared record IDs were not found and are omitted.';records=records.filter(x=>x.row);items=records.map(x=>x.item);const p=new URLSearchParams({entries:items.map(x=>x.table+':'+x.id).join(','),diff:$('#differences').checked?'1':'0'});history.replaceState(null,'','?'+p);if(!records.length){$('#comparison').innerHTML='<p>Add entries above, or use Compare from a record or character profile.</p>';return}const fields=[...new Set(records.flatMap(x=>Object.keys(x.row.fields)))].sort(),different=f=>records.some(x=>canonical(x.row.fields[f])!==canonical(records[0].row.fields[f]));$('#comparison').innerHTML=`<table><thead><tr><th>Stored field</th>${records.map(({item,row},i)=>`<th>${media[item.table+':'+row.id]?.image?`<img src="data/visual/${esc(media[item.table+':'+row.id].image)}" alt="">`:''}<a href="index.html?table=${item.table}&record=${row.id}#${item.table}">${esc(media[item.table+':'+row.id]?.name||row.fields.Name||row.id)}</a><small>${item.table} · #${row.id}${i===0?' · reference column':''}</small><button data-remove="${i}">Remove</button></th>`).join('')}</tr></thead><tbody>${fields.filter(f=>!$('#differences').checked||different(f)).map(f=>`<tr><th>${esc(f)}</th>${records.map(({row},i)=>{const v=row.fields[f],ref=records[0].row.fields[f],changed=i>0&&canonical(v)!==canonical(ref);return `<td class="${changed?'changed':''}">${v===undefined?'—':v!==null&&typeof v==='object'?`<details><summary>View nested values</summary><pre>${esc(JSON.stringify(v,null,2))}</pre></details>`:esc(String(v))}${changed&&typeof v==='number'&&typeof ref==='number'&&!/(^Id$|Id$|^DefaultWeapon|^EvolveTo$|^Rank$)/.test(f)?`<small>Δ ${v-ref>=0?'+':''}${Number((v-ref).toPrecision(8))} vs first</small>`:''}</td>`}).join('')}</tr>`).join('')||'<tr><td colspan="5">No differences. Turn off the filter to see all fields.</td></tr>'}</tbody></table>`}
async function update(){Atlas.setCompare(items);await render()}
try{const r=await fetch('data/visual/record-media.json');if(r.ok)media=await r.json();items=params.has('entries')?params.get('entries').split(',').map(k=>{const [table,id]=k.split(':');return {table,id}}).filter(x=>allowed.includes(x.table)&&/^\d+$/.test(x.id)).slice(0,4):Atlas.get('atlas-compare').filter(x=>allowed.includes(x.table)).slice(0,4);items=items.filter((x,i,a)=>a.findIndex(y=>y.table===x.table&&String(y.id)===String(x.id))===i);$('#differences').checked=params.get('diff')!=='0';await render();await search();$('#compare-table').onchange=search;let timer;$('#compare-query').oninput=()=>{clearTimeout(timer);timer=setTimeout(search,180)};$('#compare-results').onclick=async e=>{const b=e.target.closest('[data-add]');if(!b)return;const table=$('#compare-table').value;if(items.some(x=>x.table===table&&String(x.id)===b.dataset.add))return;if(items.length===4){$('#compare-status').textContent='Remove an entry before adding another (maximum four).';return}items.push({table,id:b.dataset.add});await update()};$('#comparison').onclick=async e=>{const b=e.target.closest('[data-remove]');if(b){items.splice(Number(b.dataset.remove),1);await update()}};$('#differences').onchange=render;$('#clear-comparison').onclick=async()=>{items=[];await update()};$('#download-comparison').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(records.map(x=>({table:x.item.table,...x.row})),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='comparison.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}}catch(e){$('#compare-status').textContent=e.message}
})();
